
#ifndef _TYPES_H_
#define _TYPES_H_

typedef unsigned char uint8;
typedef unsigned short int uint16;
typedef unsigned int uint32; /* SPMP-OS portability fix: 32 bits on LP64 hosts */

typedef signed char int8;
typedef signed short int int16;
typedef signed int int32; /* SPMP-OS portability fix */

#endif /* _TYPES_H_ */

